def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def relative_files(root: Path) -> list[Path]:
    return sorted(
        (path for path in root.rglob("*") if path.is_file() and path.name != MANIFEST_NAME),
        key=lambda path: path.relative_to(root).as_posix(),
    )

def _summary_heading_errors(text: str, changed: bool) -> list[str]:
    if not changed:
        return []
    headings = {
        re.sub(r"\s+", "", line.lstrip().lstrip("#").strip())
        for line in text.splitlines()
        if line.lstrip().startswith("#")
    }
    return [heading for heading in _REQUIRED_CHANGE_HEADINGS if heading not in headings]

def sessions_status(output: Path) -> dict[str, Any]:
    directory = output.resolve() / "workspace-meta/sessions"
    sessions = []
    if directory.is_dir():
        for path in sorted(directory.glob("session-*.json")):
            value = json_load(path)
            if value.get("session_id"):
                sessions.append(
                    {
                        "session_id": value["session_id"],
                        "status": value.get("status"),
                        "question": value.get("question"),
                        "started_at_utc": value.get("started_at_utc"),
                        "completed_at_utc": value.get("completed_at_utc"),
                        "record": str(path.resolve()),
                    }
                )
    return {
        "schema_version": SESSION_SCHEMA_VERSION,
        "status": "ready",
        "active": sum(item["status"] == "active" for item in sessions),
        "complete": sum(item["status"] == "complete" for item in sessions),
        "sessions": sessions,
    }

def _managed_block(text: str) -> str:
    return f"{POLICY_BEGIN}
{text.rstrip()}
{POLICY_END}
"

def _replace_managed_block(existing: str, block: str) -> str:
    pattern = re.compile(re.escape(POLICY_BEGIN) + r".*?" + re.escape(POLICY_END) + r"\n?", re.DOTALL)
    matches = pattern.findall(existing)
    if len(matches) > 1:
        raise CkbError("workspace instruction file contains duplicate CKB Agent protocol blocks")
    if matches:
        return pattern.sub(lambda _match: block, existing, count=1)
    if not existing.strip():
        return block
    return existing.rstrip() + "\n\n" + block

def _instruction_roots(output: Path) -> dict[str, Path]:
    roots = {"output": output.resolve()}
    for name in ("markdown", "human"):
        path = (output / name).resolve()
        if path.is_dir():
            roots[name] = path
    return roots

def _hide_protocol_files(output: Path) -> None:
    """Keep Harness adapters out of the human Obsidian navigation surface."""
    for name in ("markdown", "human"):
        root = output / name
        app_path = root / ".obsidian/app.json"
        if app_path.is_file():
            app = json_load(app_path)
            app["userIgnoreFilters"] = list(dict.fromkeys([*app.get("userIgnoreFilters", []), *OBSIDIAN_IGNORES]))
            json_write(app_path, app)
        css_path = root / ".obsidian/snippets/ckb.css"
        if css_path.is_file():
            css = css_path.read_text(encoding="utf-8")
            if OBSIDIAN_HIDE_CSS not in css:
                css_path.write_text(css.rstrip() + "\n" + OBSIDIAN_HIDE_CSS + "\n", encoding="utf-8", newline="\n")

def _load_record(output: Path) -> dict[str, Any] | None:
    path = output / "workspace-meta/agent-protocol.json"
    return json_load(path) if path.is_file() else None

def _resolve_runtime(record: dict[str, Any] | None, python: Path | None, ckb: Path | None) -> tuple[Path, Path]:
    python_path = python or (Path(str(record["python"])) if record and record.get("python") else _default_python())
    ckb_path = ckb or (Path(str(record["ckb"])) if record and record.get("ckb") else _default_ckb())
    if not python_path.is_file():
        raise CkbError(f"Agent protocol Python executable is missing: {python_path}")
    if not ckb_path.is_file():
        raise CkbError(f"Agent protocol CKB entrypoint is missing: {ckb_path}")
    return python_path.resolve(), ckb_path.resolve()

def _workspace_root_allowed(root: Path, output: Path, repository: str) -> bool:
    if path_inside(output.resolve(), root.resolve()):
        return True
    repo = Path(repository)
    return repo.is_absolute() and path_inside(repo.resolve(), root.resolve())

def install_agent_protocol(
    output: Path,
    workspace_roots: list[Path],
    *,
    python: Path | None = None,
    ckb: Path | None = None,
) -> dict[str, Any]:
    """Install internal adapters and managed blocks at Harness task roots."""
    output = output.resolve()
    record = project_agent_protocol(output, python=python, ckb=ckb)
    protocol = _protocol_text(output, record["repository"], Path(record["python"]), Path(record["ckb"]))
    texts = _adapter_texts(protocol)
    requested = {Path(str(value["root"])).resolve() for value in record.get("workspace_roots", [])}
    requested.update(root.resolve() for root in workspace_roots)
    merged: dict[str, dict[str, Any]] = {}
    for root in sorted(requested, key=str):
        if not root.is_dir():
            raise CkbError(f"Agent protocol workspace root is missing: {root}")
        if not _workspace_root_allowed(root, output, record["repository"]):
            raise CkbError(f"Agent protocol workspace root must contain the repository or knowledge output: {root}")
        merged[str(root)] = _write_workspace_root(root, texts)
    record["workspace_roots"] = [merged[key] for key in sorted(merged)]
    json_write(output / "workspace-meta/agent-protocol.json", record)
    audit = audit_agent_protocol(output)
    if audit["status"] != "passed":
        raise AuditError(f"Agent protocol audit failed: {output / 'workspace-meta/agent-protocol-audit.json'}")
    return {**record, "audit": audit}

def _expected_internal(output: Path, record: dict[str, Any]) -> tuple[dict[str, str], dict[str, Path]]:
    protocol = _protocol_text(output, str(record["repository"]), Path(record["python"]), Path(record["ckb"]))
    return _adapter_texts(protocol), _instruction_roots(output)

def _audit_note_storage(output: Path) -> list[dict[str, Any]]:
    errors = list(audit_notes(output))
    human = output / "human"
    markdown = output / "markdown"
    meta_root = output / "workspace-meta/notes"
    notes: dict[str, dict[str, Any]] = {}
    for directory in NOTE_DIRECTORIES:
        left = {path.name: path for path in (human / directory).glob("*.md")}
        right = {path.name: path for path in (markdown / directory).glob("*.md")}
        if set(left) != set(right):
            errors.append({"reason": "agent-note-mirror-set-mismatch", "directory": directory, "human_only": sorted(set(left) - set(right)), "markdown_only": sorted(set(right) - set(left))})
        for name in sorted(set(left) & set(right)):
            if left[name].read_bytes() != right[name].read_bytes():
                errors.append({"reason": "agent-note-mirror-byte-mismatch", "path": f"{directory}/{name}"})
                continue
            text = right[name].read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else ""
            relative = f"{directory}/{name}"
            notes[title] = {"relative": relative, "content": text, "kind": next((kind for kind, value in DIRECTORY_BY_KIND.items() if value == directory), "")}
            meta = meta_root / f"{safe_title(title)}.json"
            if not meta.is_file():
                errors.append({"reason": "agent-note-metadata-missing", "path": relative, "title": title})
                continue
            value = json_load(meta)
            if value.get("status") != "agent-reviewed" or value.get("title") != title or value.get("kind") != notes[title]["kind"]:
                errors.append({"reason": "agent-note-metadata-invalid", "path": relative, "metadata": str(meta)})

    index = output / "agent-index.sqlite"
    if index.is_file():
        connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
        try:
            integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
            indexed = {row[0]: {"file": row[1], "content": row[2]} for row in connection.execute("SELECT note_title,note_file,content FROM notes")}
        except sqlite3.DatabaseError as exc:
            errors.append({"reason": "agent-index-read-failed", "detail": str(exc)})
            indexed = {}
            integrity = "error"
        finally:
            connection.close()
        if integrity != "ok":
            errors.append({"reason": "agent-index-integrity", "detail": integrity})
        for title, note in notes.items():
            row = indexed.get(title)
            if row != {"file": note["relative"], "content": note["content"]}:
                errors.append({"reason": "agent-index-note-stale", "title": title, "path": note["relative"]})
        if set(indexed) != set(notes):
            errors.append({"reason": "agent-index-note-set-mismatch", "index_only": sorted(set(indexed) - set(notes)), "file_only": sorted(set(notes) - set(indexed))})
    else:
        errors.append({"reason": "agent-index-missing"})

    machine = output / "machine/knowledge.sqlite"
    if machine.is_file():
        connection = sqlite3.connect(f"file:{machine.as_posix()}?mode=ro", uri=True)
        try:
            integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
            indexed = {
                row[0]: {"file": row[1], "content": row[2], "kind": row[3]}
                for row in connection.execute("SELECT title,human_file,content,kind FROM documents WHERE kind NOT IN ('entity','reference','gap')")
            }
        except sqlite3.DatabaseError as exc:
            errors.append({"reason": "machine-index-read-failed", "detail": str(exc)})
            indexed = {}
            integrity = "error"
        finally:
            connection.close()
        if integrity != "ok":
            errors.append({"reason": "machine-index-integrity", "detail": integrity})
        for title, note in notes.items():
            row = indexed.get(title)
            if row != {"file": note["relative"], "content": note["content"], "kind": note["kind"]}:
                errors.append({"reason": "machine-index-note-stale", "title": title, "path": note["relative"]})
        if set(indexed) != set(notes):
            errors.append({"reason": "machine-index-note-set-mismatch", "index_only": sorted(set(indexed) - set(notes)), "file_only": sorted(set(notes) - set(indexed))})
    else:
        errors.append({"reason": "machine-index-missing"})
    return errors

def agent_protocol_status(output: Path) -> dict[str, Any]:
    record = _load_record(output.resolve())
    return {
        "schema_version": AGENT_PROTOCOL_SCHEMA_VERSION,
        "status": "installed" if record else "missing",
        "record": record,
        "audit": audit_agent_protocol(output.resolve()) if record else None,
    }

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def background_process_options(*, visible: bool = False) -> dict[str, Any]:
    """Hide non-interactive Windows child consoles without changing I/O semantics."""
    if visible or os.name != "nt":
        return {}
    creation_flag = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return {"creationflags": creation_flag} if creation_flag else {}

def command_version(executable: str, args: Iterable[str] = ("--version",)) -> dict[str, Any]:
    resolved = shutil.which(executable)
    if not resolved:
        return {"status": "missing", "command": executable, "path": None, "version": None}
    completed = run([resolved, *args], timeout=20)
    text = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "status": "ready" if completed.returncode == 0 else "broken",
        "command": executable,
        "path": str(Path(resolved).resolve()),
        "version": text[0] if text else None,
        "exit_status": completed.returncode,
    }

def clear_markers(output: Path) -> None:
    for name in (
        ".pending-agent-review",
        ".failed",
        ".complete",
        ".machine.complete",
        ".human.complete",
    ):
        (output / name).unlink(missing_ok=True)

def write_marker(output: Path, name: str, payload: dict[str, Any]) -> None:
    clear_markers(output)
    json_write(output / name, payload)

def safe_title(text: str, limit: int = 120) -> str:
    value = re.sub(r"[\\/:*?\"<>|\[\]]+", "-", text).strip(" .-")
    return (value[:limit] or "untitled").strip()

def path_inside(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False

def safe_rmtree(path: Path, root: Path) -> None:
    """Remove one verified descendant without ever accepting the root itself."""
    resolved_path = path.resolve()
    resolved_root = root.resolve()
    if resolved_path == resolved_root or not path_inside(resolved_path, resolved_root):
        raise CkbError(f"recursive removal target is outside its declared root: {resolved_path}")
    if resolved_path.exists():
        shutil.rmtree(resolved_path)

def prepare_feedback_store(output: Path) -> dict[str, Any]:
    """Create only the feedback-owned directories for a finalized Markdown KB."""
    output = output.resolve()
    metadata = output / "workspace-meta/feedback"
    for status in STATUS_DIRECTORY.values():
        (metadata / status).mkdir(parents=True, exist_ok=True)
    vaults = []
    for name in ("markdown", "human"):
        root = output / name
        if root.is_dir():
            for relative in FEEDBACK_DIRECTORIES:
                (root / relative).mkdir(parents=True, exist_ok=True)
            vaults.append(str(root.resolve()))
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "metadata_root": str(metadata.resolve()),
        "vaults": vaults,
    }

def _canonical_relative_target(output: Path, target: Path) -> tuple[str, Path, Path]:
    output = output.resolve()
    human = output / "human"
    markdown = output / "markdown"
    if not human.is_dir() or not markdown.is_dir():
        raise CkbError("feedback requires finalized human and markdown knowledge roots")
    raw = str(target).replace("\\", "/")
    candidate = Path(target)
    if candidate.is_absolute():
        resolved = candidate.resolve()
        if path_inside(resolved, human):
            relative = resolved.relative_to(human).as_posix()
        elif path_inside(resolved, markdown):
            relative = resolved.relative_to(markdown).as_posix()
        else:
            raise CkbError("feedback target must be inside OUTPUT/human or OUTPUT/markdown")
    else:
        for prefix in ("human/", "markdown/"):
            if raw.startswith(prefix):
                raw = raw[len(prefix) :]
                break
        pure = PurePosixPath(raw)
        if pure.is_absolute() or ".." in pure.parts:
            raise CkbError("feedback target must be a knowledge-root relative path")
        relative = pure.as_posix().lstrip("./")
    if not relative or relative.startswith("feedback/") or not relative.endswith(".md"):
        raise CkbError("feedback target must be a non-feedback Markdown knowledge page")
    human_target = human / relative
    markdown_target = markdown / relative
    if not human_target.is_file() or not markdown_target.is_file():
        raise CkbError(f"feedback target is missing from the mirrored human knowledge roots: {relative}")
    if human_target.read_bytes() != markdown_target.read_bytes():
        raise CkbError(f"feedback target differs between human and markdown roots: {relative}")
    return relative, human_target, markdown_target

def _read_chinese_body(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} body does not exist: {path}")
    value = path.read_text(encoding="utf-8-sig").strip()
    if not value:
        raise CkbError(f"{label} body must not be empty")
    if not _contains_chinese(value):
        raise CkbError(f"{label} narrative must use Simplified Chinese")
    if value.startswith("---\n") or LONG_HEX.search(value):
        raise CkbError(f"{label} body must omit frontmatter and hash-like identifiers")
    return value

def _line_selection(text: str, start_line: int, end_line: int) -> tuple[str, str, str]:
    if start_line < 1 or end_line < start_line:
        raise CkbError("feedback line range must be a positive inclusive range")
    lines = text.splitlines(keepends=True)
    if end_line > len(lines):
        raise CkbError(f"feedback line range exceeds target length: {end_line}>{len(lines)}")
    start_offset = sum(len(value) for value in lines[: start_line - 1])
    end_offset = sum(len(value) for value in lines[:end_line])
    anchor_text = text[start_offset:end_offset]
    if not anchor_text:
        raise CkbError("feedback selection must not be empty")
    return text[max(0, start_offset - 80) : start_offset], anchor_text, text[end_offset : end_offset + 80]

def _next_feedback_id(output: Path) -> str:
    prefix = dt.datetime.now(dt.timezone.utc).strftime("feedback-%Y%m%d-%H%M%S")
    existing = {
        path.stem
        for status in STATUS_DIRECTORY.values()
        for path in (output / "workspace-meta/feedback" / status).glob(f"{prefix}-*.json")
    }
    index = 1
    while f"{prefix}-{index:02d}" in existing:
        index += 1
    return f"{prefix}-{index:02d}"

def _blockquote(value: str) -> str:
    lines = value.rstrip("\n").splitlines() or [""]
    return "\n".join("> " + line for line in lines)

def _load_feedback(output: Path, feedback_id: str) -> tuple[dict[str, Any], Path]:
    if not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
        raise CkbError("feedback identifier has an invalid shape")
    matches = [path for status in STATUS_DIRECTORY for path in [_record_path(output, status, feedback_id)] if path.is_file()]
    if len(matches) != 1:
        raise CkbError(f"feedback identifier must resolve to exactly one record: {feedback_id}")
    return json_load(matches[0]), matches[0]

def _all_offsets(text: str, needle: str) -> list[int]:
    offsets = []
    start = 0
    while needle:
        value = text.find(needle, start)
        if value < 0:
            break
        offsets.append(value)
        start = value + 1
    return offsets

def _locate_anchor(text: str, record: dict[str, Any]) -> dict[str, Any]:
    start_line, end_line = [int(value) for value in record["target_lines"]]
    lines = text.splitlines(keepends=True)
    if 1 <= start_line <= end_line <= len(lines):
        start = sum(len(value) for value in lines[: start_line - 1])
        end = sum(len(value) for value in lines[:end_line])
        if record["anchor_text"] in text[start:end]:
            return {"status": "line-range", "current_lines": [start_line, end_line], "match_count": 1}
    offsets = _all_offsets(text, str(record["anchor_text"]))
    if len(offsets) == 1:
        start = offsets[0]
        return {
            "status": "unique-text",
            "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
            "match_count": 1,
        }
    if len(offsets) > 1:
        window = str(record["anchor_before"]) + str(record["anchor_text"]) + str(record["anchor_after"])
        windows = _all_offsets(text, window)
        if len(windows) == 1:
            start = windows[0] + len(record["anchor_before"])
            return {
                "status": "anchor-window",
                "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
                "match_count": len(offsets),
            }
    return {"status": "stale", "current_lines": None, "match_count": len(offsets)}

def _canonical_applied_record(output: Path, path: Path | None) -> str | None:
    if path is None:
        return None
    resolved = path.resolve()
    if not resolved.is_file() or not path_inside(resolved, output.resolve()):
        raise CkbError("applied record must be an existing file inside the knowledge output")
    relative = resolved.relative_to(output.resolve())
    if len(relative.parts) < 3 or relative.parts[0] not in {"human", "markdown"}:
        raise CkbError("applied record must point to a reviewed human knowledge note")
    note_directories = {"analysis", "changes", "pitfalls", "experiments", "sessions"}
    if relative.parts[1] not in note_directories or resolved.suffix.casefold() != ".md":
        raise CkbError("applied record must point to an analysis, change, pitfall, experiment, or session note")
    note_relative = Path(*relative.parts[1:])
    human = output / "human" / note_relative
    markdown = output / "markdown" / note_relative
    if not human.is_file() or not markdown.is_file() or human.read_bytes() != markdown.read_bytes():
        raise CkbError("applied record must have byte-identical human and markdown note mirrors")
    title = _title_of(human)
    metadata = output / "workspace-meta/notes" / f"{safe_title(title)}.json"
    if not metadata.is_file():
        raise CkbError("applied record metadata is missing; create the note through record")
    value = json_load(metadata)
    if value.get("status") != "agent-reviewed" or value.get("title") != title:
        raise CkbError("applied record must have agent-reviewed metadata")
    return relative.as_posix()
